insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0003-0000-4000-8000-000000000013', 'en', null, 'Business Analytics', 'Turn raw business data into decisions — describing what happened, forecasting what is next, and recommending what to do, using summaries, probability, sampling, testing, and regression grounded in real operating questions. Structure adapted from OpenStax Introductory Business Statistics (CC BY 4.0).', null, 'career', 19, true, 'business', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0003-0000-4000-8000-000000000013', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Analytics that reports what already happened, such as last quarter''s total revenue, is called…","options":["predictive analytics","descriptive analytics","prescriptive analytics","diagnostic sampling"],"answer":1,"explanation":"Descriptive analytics summarizes the past — see ''What business analytics is''."},{"prompt":"Monthly sales region (North, South, East, West) is what type of data?","options":["continuous numerical","discrete numerical","categorical","time series only"],"answer":2,"explanation":"Regions are labels with no numeric order, so the data is categorical — see ''Data types and summarizing data''."},{"prompt":"The best single chart to show one product''s monthly sales trend over a year is a…","options":["pie chart","line chart","scatter plot of unrelated variables","word cloud"],"answer":1,"explanation":"A line chart shows change over ordered time — see ''Visualizing data and dashboards''."},{"prompt":"For the daily sales 4, 4, 5, 6, 31, which measure of center best represents a typical day?","options":["the mean","the median","the maximum","the range"],"answer":1,"explanation":"The median resists the outlier 31; the mean is pulled upward by it."},{"prompt":"If an order ships on time with probability 0.9, the probability it is late is…","options":["0.9","0.1","0.5","0.01"],"answer":1,"explanation":"Complement rule: P(late) = 1 - 0.9 = 0.1."},{"prompt":"A 95% confidence interval for average order value is a range that…","options":["contains every customer''s order","is our best plausible range for the true average","guarantees the next order falls inside","has no relation to sample size"],"answer":1,"explanation":"It is a plausible range for the population mean built from a sample — see ''Sampling and confidence intervals''."},{"prompt":"A hypothesis test returns a p-value of 0.02 at the 0.05 significance level. You should…","options":["fail to reject the null hypothesis","reject the null hypothesis","conclude the null is certainly true","double the sample and ignore it"],"answer":1,"explanation":"0.02 is below 0.05, so the result is statistically significant and you reject the null — see ''Hypothesis testing''."},{"prompt":"A correlation of r = 0.85 between ad spend and sales means…","options":["ad spend causes sales","a strong positive linear association","no relationship","sales cause ad spend"],"answer":1,"explanation":"Correlation measures linear association, not causation — see ''Correlation, regression, and forecasting''."}]}'::jsonb, null, 10),
  (2, 'What business analytics is: descriptive, predictive, prescriptive', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Sort any business question into descriptive, predictive, or prescriptive analytics, and explain what each layer adds. Warm-up: from the diagnostic, which layer does ''last quarter''s total revenue'' belong to?"},{"heading":"The idea","text":"Business analytics is the practice of using data to make better decisions. It comes in three layers that build on each other. Descriptive analytics summarizes what already happened: totals, averages, trends, and dashboards that report the past. Predictive analytics uses patterns in past data to estimate what is likely to happen next, such as forecasting next month''s demand or which customers may cancel. Prescriptive analytics goes one step further and recommends an action, weighing options and constraints to suggest what to do, for example how much inventory to order. Most real projects move up the ladder: you first describe, then predict, then prescribe. Each layer answers a sharper question and carries more responsibility, because a recommendation that drives spending must rest on solid description and prediction underneath."},{"heading":"Worked examples","text":"1) ''Our average delivery time last month was 3.2 days'' is descriptive — it reports the past. 2) ''Based on the last two years, December demand will be about 20 percent above November'' is predictive — it projects forward from a pattern. 3) ''To hit a 98 percent in-stock rate at lowest cost, order 4,000 units now'' is prescriptive — it recommends an action under a goal and a constraint. 4) A churn dashboard showing that 6 percent of subscribers left last quarter is descriptive; a model flagging which current subscribers are most likely to leave is predictive; a rule that offers those subscribers a discount is prescriptive."},{"heading":"Your turn","text":"Label each as descriptive, predictive, or prescriptive. 1) ''Set the thermostat schedule that minimizes energy cost next week.'' 2) ''Total tickets sold this year rose 12 percent.'' 3) ''This lead has a 70 percent chance of converting.'' 4) ''Reorder point should be 150 units to avoid stockouts.'' 5) ''The median basket size in July was 32 dollars.'' Answers: 1) prescriptive — it recommends an action to minimize cost. 2) descriptive — it summarizes the past. 3) predictive — it estimates a future outcome. 4) prescriptive — it recommends a decision value. 5) descriptive — it reports a past summary."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling a forecast ''prescriptive'' — a forecast predicts, but until it names an action it is only predictive. Mistake: jumping to a recommendation before you have described the data honestly. Exit: (a) Which layer recommends an action? (b) Which layer only summarizes the past? Answers: prescriptive; descriptive."}]}'::jsonb, 'Descriptive answers ''what happened'', predictive answers ''what is likely next'', and prescriptive answers ''what should we do'' — always name which question you are actually answering.', 12),
  (3, 'Data types and summarizing data', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Classify a variable as categorical or numerical (and numerical as discrete or continuous), and summarize a column with counts, proportions, or averages appropriately. Warm-up: is ''payment method'' something you can take an average of?"},{"heading":"The idea","text":"Every column of business data has a type that decides how you may summarize it. Categorical data are labels or groups with no numeric meaning, such as region, product category, or yes/no. You summarize categorical data with counts and proportions (a proportion is a count divided by the total). Numerical data are quantities you can do arithmetic on. Numerical data split into discrete, meaning countable whole units such as number of orders, and continuous, meaning measured on a scale that can take any value in a range such as revenue or delivery time. You summarize numerical data with measures of center (mean, median) and spread (range, variance, standard deviation). A frequency table lists each category with its count and proportion; it is the first thing to build before charting."},{"heading":"Worked examples","text":"1) ''Customer tier: Bronze, Silver, Gold'' is categorical; summarize it as ''Gold = 40 of 200 = 0.20, i.e. 20 percent.'' 2) ''Number of items per order'' is discrete numerical; you can average it: (1 + 2 + 3 + 2) / 4 = 2 items. 3) ''Order value in dollars'' is continuous numerical; mean of 10, 20, 30 is 60 / 3 = 20. 4) A frequency table for 10 orders paid by Card (6), Cash (3), Transfer (1) gives proportions 0.6, 0.3, 0.1, which sum to 1.0 — a useful check."},{"heading":"Your turn","text":"1) Classify ''ZIP code'' — numerical or categorical? 2) Classify ''number of support calls per day.'' 3) Classify ''website session length in seconds.'' 4) Of 50 sign-ups, 35 chose the monthly plan; what proportion is that? 5) For order counts 3, 5, 5, 7, what is the mean? Answers: 1) categorical — the digits are labels, not quantities you would average. 2) discrete numerical — countable whole calls. 3) continuous numerical — a measured scale. 4) 35 / 50 = 0.70, or 70 percent. 5) (3 + 5 + 5 + 7) / 4 = 20 / 4 = 5."},{"heading":"Common mistakes & exit ticket","text":"Mistake: averaging a categorical code, like treating ZIP codes as numbers — the average ZIP means nothing. Mistake: forgetting proportions must sum to 1 across all categories. Exit: (a) How do you summarize categorical data? (b) Is delivery time discrete or continuous? Answers: counts and proportions; continuous."}]}'::jsonb, 'You can average numerical data but not categorical data — you can only count categories and report proportions.', 13),
  (4, 'Visualizing data and dashboards for decisions', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Choose the right chart for a business question, read a histogram, and lay out a dashboard around a few key performance indicators (KPIs). Warm-up: to show one store''s revenue month by month, which chart fits best?"},{"heading":"The idea","text":"A chart is a tool to answer a specific question fast. Use a bar chart to compare a numeric value across categories, such as revenue by region. Use a line chart to show a trend over ordered time, such as weekly sign-ups. Use a histogram to show the distribution of one numerical variable by grouping values into bins and counting how many fall in each — it reveals shape, center, and outliers. Use a scatter plot to show the relationship between two numerical variables, such as ad spend versus sales. A dashboard is a small collection of these views built around KPIs, the handful of numbers that track progress toward a goal, like conversion rate or on-time delivery rate. A good KPI is specific, measurable, and tied to a decision; a good dashboard shows the current value, a target, and a trend so a reader can act at a glance."},{"heading":"Worked examples","text":"1) ''Compare total sales across four regions'' — a bar chart, one bar per region. 2) ''Show daily active users across the last 90 days'' — a line chart, time on the horizontal axis. 3) ''How are order values distributed, and are there extreme orders?'' — a histogram; a long right tail signals a few very large orders. 4) ''Does spending more on ads relate to more sales?'' — a scatter plot of ad spend versus sales. 5) A retention dashboard might carry three KPIs: monthly churn rate (target below 5 percent), average revenue per user (trend line), and net new subscribers (bar per month)."},{"heading":"Your turn","text":"Pick the best chart for each. 1) Market share of five competitors. 2) A factory''s defect rate each week this year. 3) The relationship between store size and monthly revenue. 4) The distribution of customer wait times. 5) Which of these is a well-formed KPI: ''be better'' or ''on-time delivery rate at or above 95 percent''? Answers: 1) a bar chart (or proportion chart) comparing shares. 2) a line chart — a weekly trend. 3) a scatter plot of two numerical variables. 4) a histogram of one numerical variable. 5) ''on-time delivery rate at or above 95 percent'' — it is specific, measurable, and has a target."},{"heading":"Common mistakes & exit ticket","text":"Mistake: using a line chart for unordered categories, which invents a trend that is not there. Mistake: a dashboard with twenty numbers and no targets, so nobody knows what action to take. Exit: (a) Which chart shows the distribution of one numerical variable? (b) What three things should a KPI tile show? Answers: a histogram; current value, target, and trend."}]}'::jsonb, 'Match the chart to the question: comparison uses bars, trend over time uses lines, parts of a whole uses proportions, and relationship between two numbers uses a scatter plot.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"''Recommend the staffing level that minimizes wait time next week'' is which kind of analytics?","options":["descriptive","predictive","prescriptive","categorical"],"answer":2,"explanation":"It recommends an action under a goal, so it is prescriptive."},{"prompt":"''Product category'' (Books, Toys, Tools) is what type of data?","options":["continuous numerical","discrete numerical","categorical","time series"],"answer":2,"explanation":"The values are labels with no numeric meaning, so the data is categorical."},{"prompt":"Of 80 visitors, 12 made a purchase. The conversion proportion is…","options":["0.12","0.15","0.68","1.5"],"answer":1,"explanation":"12 / 80 = 0.15, or 15 percent."},{"prompt":"To show weekly website traffic over a year, the best chart is a…","options":["pie chart","line chart","histogram","scatter plot"],"answer":1,"explanation":"Traffic is a trend over ordered time, which a line chart shows."},{"prompt":"The mean of the order values 8, 10, 12, 10 is…","options":["9","10","12","40"],"answer":1,"explanation":"(8 + 10 + 12 + 10) / 4 = 40 / 4 = 10."},{"prompt":"A chart that shows the distribution and shape of a single numerical variable is a…","options":["bar chart of categories","histogram","pie chart","line chart"],"answer":1,"explanation":"A histogram bins one numerical variable to reveal its shape, center, and outliers."}]}'::jsonb, null, 8),
  (6, 'Descriptive statistics and probability for risk', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute the mean, median, variance, and standard deviation of a business dataset, and use basic probability rules to reason about risk. Warm-up: for the daily sales 4, 4, 5, 6, 31, which is more typical, the mean or the median?"},{"heading":"The idea","text":"Measures of center summarize a typical value. The mean is the sum divided by the count. The median is the middle value when the data are sorted (the average of the two middle values if the count is even); it resists outliers, which is why skewed money data often report the median. Measures of spread say how variable the data are. The range is max minus min. The variance is the average of the squared distances from the mean, and the standard deviation is the square root of the variance, back in the original units. Probability quantifies risk. A probability is a number from 0 to 1. The complement rule says P(not A) = 1 - P(A). For independent events, P(A and B) = P(A) times P(B). Expected value weights each outcome by its probability: E = sum of (value times probability), the long-run average payoff of a decision."},{"heading":"Worked examples","text":"For 4, 4, 5, 6, 31: mean = 50 / 5 = 10, but the sorted middle value is 5, so median = 5 — the 31 inflates the mean. Variance: deviations from the mean 10 are -6, -6, -5, -4, 21; squares 36, 36, 25, 16, 441 sum to 554; dividing by 5 gives variance 110.8, so standard deviation is about 10.5. Probability: if an order ships on time with probability 0.9, then P(late) = 1 - 0.9 = 0.1. Independence: two machines each fail with probability 0.05; P(both fail) = 0.05 times 0.05 = 0.0025. Expected value: a promotion yields 100 dollars profit with probability 0.6 and a 50 dollar loss with probability 0.4, so E = 0.6(100) + 0.4(-50) = 60 - 20 = 40 dollars expected profit."},{"heading":"Your turn","text":"1) Find the mean and median of 2, 3, 3, 10. 2) What is the range of 12, 15, 20? 3) If a payment succeeds with probability 0.8, what is P(it fails)? 4) Two independent servers each go down with probability 0.1; what is P(both down)? 5) A bet pays 200 dollars with probability 0.3 and loses 100 dollars with probability 0.7; what is the expected value? Answers: 1) mean = 18 / 4 = 4.5; median = (3 + 3) / 2 = 3. 2) 20 - 12 = 8. 3) 1 - 0.8 = 0.2. 4) 0.1 times 0.1 = 0.01. 5) 0.3(200) + 0.7(-100) = 60 - 70 = -10 dollars, a losing bet on average."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reporting the mean for skewed money data where a few large values mislead — prefer the median there. Mistake: multiplying probabilities for events that are not independent. Exit: (a) Which measure of center resists outliers? (b) What is the expected value of a coin flip paying 10 dollars on heads and 0 on tails? Answers: the median; 0.5(10) + 0.5(0) = 5 dollars."}]}'::jsonb, 'Center tells you the typical value; spread tells you how risky or variable it is — a decision needs both.', 15),
  (7, 'Sampling, confidence intervals, and hypothesis testing', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read a confidence interval for an average or proportion, and run the logic of a hypothesis test to decide whether a business result is real or just chance. Warm-up: if you survey 200 of your 50,000 customers, what are you trying to learn about the whole?"},{"heading":"The idea","text":"You rarely measure everyone, so you take a sample and use it to estimate a population value such as a mean or a proportion. A random sample keeps the estimate unbiased; a biased sample (for example, only asking happy customers) distorts it. Because a sample is only part of the whole, the estimate has uncertainty. A confidence interval is a range around the estimate that, at a stated confidence level such as 95 percent, is our plausible range for the true population value. Larger samples give narrower intervals. A hypothesis test asks whether a difference we see is more than random noise. The null hypothesis says there is no effect (for example, a new page has the same conversion rate as the old one). The p-value is the probability of seeing a result at least this extreme if the null were true. If the p-value is below the chosen significance level (often 0.05), we reject the null and call the result statistically significant; otherwise we fail to reject it. Statistical significance is not the same as business importance — a tiny effect can be significant with a huge sample."},{"heading":"Worked examples","text":"1) A survey of 400 customers gives a mean order value of 52 dollars with a 95 percent confidence interval of 49 to 55 dollars; we read this as: the true average order value is plausibly between 49 and 55 dollars. 2) An A/B test finds the new checkout converts at 12 percent versus 10 percent for the old, with a p-value of 0.03. Since 0.03 is below 0.05, we reject the null of ''no difference'' and adopt the new checkout. 3) A different test shows 10.1 percent versus 10.0 percent with a p-value of 0.4; we fail to reject the null — the gap is within noise. 4) Doubling a sample from 100 to 400 roughly halves the interval width, because precision improves with the square root of the sample size."},{"heading":"Your turn","text":"1) A 95 percent interval for churn is 4 to 6 percent; is a claimed 8 percent inside it? 2) A test returns p = 0.01 at the 0.05 level — reject or fail to reject the null? 3) A test returns p = 0.20 at the 0.05 level — reject or fail to reject? 4) To shrink a confidence interval, should you collect more or less data? 5) Does a statistically significant 0.1 percent lift necessarily justify a costly rebuild? Answers: 1) no — 8 percent lies outside 4 to 6 percent. 2) reject the null; 0.01 is below 0.05. 3) fail to reject; 0.20 is above 0.05. 4) more data narrows the interval. 5) no — significance is not the same as a business payoff worth the cost."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reading a confidence interval as covering individual customers rather than the population average. Mistake: treating ''fail to reject'' as proof the null is true — it only means the evidence is not strong enough. Exit: (a) What does a p-value below 0.05 lead you to do with the null? (b) Does a larger sample widen or narrow a confidence interval? Answers: reject it; narrow it."}]}'::jsonb, 'A sample estimates a population; a confidence interval reports the uncertainty in that estimate, and a hypothesis test decides whether an observed difference is more than noise.', 15),
  (8, 'Correlation, regression, and forecasting', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Interpret a correlation coefficient, read a simple linear regression line, and use it to make a forecast. Warm-up: if ad spend and sales have a correlation of 0.85, does that alone prove ads cause sales?"},{"heading":"The idea","text":"Correlation, written r, measures the strength and direction of a linear relationship between two numerical variables. It ranges from -1 to 1: near 1 is a strong positive association (both rise together), near -1 is a strong negative association (one rises as the other falls), and near 0 means little linear relationship. Correlation does not prove causation — a lurking third variable can drive both. Simple linear regression fits a straight line y = a + b x, where x is the predictor (input) and y is the response (output). The slope b is the estimated change in y for each one-unit increase in x, and the intercept a is the predicted y when x is 0. You forecast by plugging an x value into the fitted line. A time-series forecast uses time as the predictor to project a trend forward, but every forecast carries uncertainty and gets shakier the further out you push it."},{"heading":"Worked examples","text":"1) r = 0.9 between store size and revenue is a strong positive association: bigger stores tend to earn more. r = -0.7 between price and units sold is a strong negative association. 2) Fitted line: sales = 2000 + 5 times (ad dollars). The slope 5 means each extra ad dollar is associated with about 5 dollars more sales; the intercept 2000 is baseline sales at zero ad spend. 3) Forecast at ad spend 1000: sales = 2000 + 5(1000) = 7000 dollars. 4) A monthly trend line units = 300 + 20 times (month number) predicts month 12 as 300 + 20(12) = 540 units. 5) Ice cream sales and drowning both rise in summer and are correlated, yet neither causes the other — heat is the lurking variable, a reminder that correlation is not causation."},{"heading":"Your turn","text":"1) Interpret r = -0.05. 2) For sales = 1000 + 8 x, what does the slope 8 mean? 3) Predict sales when x = 50 for that line. 4) A line demand = 500 - 3 times (price); what is predicted demand at price 100? 5) True or false: a high correlation between two variables proves one causes the other. Answers: 1) almost no linear relationship. 2) each one-unit rise in x is associated with about 8 more sales. 3) 1000 + 8(50) = 1400. 4) 500 - 3(100) = 200 units. 5) false — correlation is not causation."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reading correlation as causation and acting on it without evidence of a mechanism. Mistake: trusting a forecast far outside the range of the data, where the linear pattern may not hold. Exit: (a) What does a regression slope tell you? (b) What does r near 0 indicate? Answers: the change in y per one-unit increase in x; little to no linear relationship."}]}'::jsonb, 'Correlation measures how two numbers move together; regression fits a line you can predict from — and neither one proves causation on its own.', 14),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"For the values 3, 3, 4, 20, the median is…","options":["3","3.5","7.5","20"],"answer":1,"explanation":"Sorted, the two middle values are 3 and 4, so the median is (3 + 4) / 2 = 3.5."},{"prompt":"If a delivery is on time with probability 0.85, the probability it is late is…","options":["0.85","0.15","0.5","0.72"],"answer":1,"explanation":"Complement rule: 1 - 0.85 = 0.15."},{"prompt":"A promotion gives 200 dollars profit with probability 0.5 and a 100 dollar loss with probability 0.5. Its expected value is…","options":["100 dollars","50 dollars","150 dollars","0 dollars"],"answer":1,"explanation":"0.5(200) + 0.5(-100) = 100 - 50 = 50 dollars."},{"prompt":"A hypothesis test at the 0.05 level returns p = 0.30. You should…","options":["reject the null hypothesis","fail to reject the null hypothesis","conclude the null is proven true","lower the level to 0.01 and reject"],"answer":1,"explanation":"0.30 is above 0.05, so the evidence is too weak to reject the null."},{"prompt":"For the regression line sales = 500 + 4 x, the predicted sales when x = 25 is…","options":["600","525","104","2500"],"answer":0,"explanation":"500 + 4(25) = 500 + 100 = 600."},{"prompt":"A correlation of r = -0.8 between price and units sold means…","options":["higher prices tend to go with fewer units","price causes demand","no relationship","higher prices tend to go with more units"],"answer":0,"explanation":"A strong negative correlation means as one rises the other tends to fall; it is association, not proven causation."}]}'::jsonb, null, 8),
  (10, 'Comprehensive capstone: analytics for a business case', 'quiz', '{"questions":[{"prompt":"A subscription company sees monthly churn of 7 percent and wants to reduce it. Reporting last quarter''s churn on a dashboard is which layer of analytics?","options":["predictive","prescriptive","descriptive","categorical"],"answer":2,"explanation":"Reporting a past number is descriptive analytics."},{"prompt":"The company''s monthly revenue is: 100, 105, 98, 500 (thousands), where 500 was a one-time enterprise deal. The best single measure of a typical month is the…","options":["mean","median","maximum","range"],"answer":1,"explanation":"The 500 outlier inflates the mean, so the median better reflects a typical month."},{"prompt":"To track churn against a target on a dashboard, the strongest KPI tile shows churn rate, its target, and…","options":["the office address","its trend over time","the CEO''s name","a random color"],"answer":1,"explanation":"A good KPI tile shows current value, target, and trend so the reader can act."},{"prompt":"A survey of 500 customers estimates satisfaction at 80 percent with a 95 percent confidence interval of 77 to 83 percent. This interval is best read as…","options":["every customer is 77 to 83 percent satisfied","the plausible range for the true satisfaction rate","a guarantee the next customer is satisfied","the sample was too small to matter"],"answer":1,"explanation":"A confidence interval is a plausible range for the population value."},{"prompt":"An A/B test of a new onboarding flow raises activation from 20 to 25 percent with a p-value of 0.01 at the 0.05 level. The correct decision is to…","options":["fail to reject the null and keep the old flow","reject the null and adopt the new flow","conclude nothing can be decided","declare the difference is certainly zero"],"answer":1,"explanation":"p = 0.01 is below 0.05, a statistically significant lift, so reject the null and adopt the new flow."},{"prompt":"If a cancellation happens independently with probability 0.07 for each of two customers, the probability that both cancel is…","options":["0.14","0.0049","0.07","0.49"],"answer":1,"explanation":"For independent events, P(both) = 0.07 times 0.07 = 0.0049."},{"prompt":"A regression gives revenue = 10000 + 3 times (marketing dollars). Spending 5000 on marketing predicts revenue of…","options":["15000","25000","13000","50000"],"answer":1,"explanation":"10000 + 3(5000) = 10000 + 15000 = 25000."},{"prompt":"Marketing spend and revenue show r = 0.9, but a holdout region with no spend still grew. The safest conclusion is…","options":["marketing certainly caused all the growth","correlation is strong but does not by itself prove causation","there is no relationship","revenue caused the marketing spend"],"answer":1,"explanation":"Correlation is not causation; the holdout growth warns of other drivers, so test before crediting the spend."},{"prompt":"A demand forecast for 24 months out based on 12 months of data should be treated as…","options":["exact and certain","increasingly uncertain the further out it projects","irrelevant to planning","more accurate than a 1-month forecast"],"answer":1,"explanation":"Forecast uncertainty grows the further beyond the data you project."},{"prompt":"Which sequence correctly moves up the analytics ladder for the churn problem?","options":["prescribe, predict, describe","describe churn, predict who will leave, prescribe a retention offer","predict, describe, ignore","prescribe first, then gather data"],"answer":1,"explanation":"You describe the past, then predict the future, then prescribe an action — each layer builds on the one below."}]}'::jsonb, null, 14)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0003-0000-4000-8000-000000000013' and l.position = v.pos
);
